#!/usr/bin/env python3
"""
TLS Configuration for IEC 61850 MMS Connections

Provides TLS support for MMSClient and TASE2Client connections
using libiec61850 TLSConfiguration API.

Example:
    from pyiec61850.mms import MMSClient
    from pyiec61850.mms.tls import TLSConfig

    tls = TLSConfig(
        own_cert="client.pem",
        own_key="client-key.pem",
        ca_certs=["ca.pem"],
    )

    with MMSClient(host="192.168.1.100", tls=tls) as client:
        print(client.get_logical_devices())
"""

import logging
from dataclasses import dataclass, field
from enum import IntEnum
from typing import Any, Dict, List, Optional

try:
    import pyiec61850.pyiec61850 as iec61850

    _HAS_IEC61850 = True
except ImportError:
    _HAS_IEC61850 = False
    iec61850 = None

from .._libload import require_library
from .exceptions import (
    LibraryNotFoundError,
    MMSError,
)
from .types import _c  # binding-constant lookup with fallback (shared with enums)

logger = logging.getLogger(__name__)


class TLSError(MMSError):
    """Error related to TLS configuration or connection."""

    def __init__(self, message: str = "TLS error"):
        super().__init__(message)


class TLSConfigError(TLSError):
    """Invalid TLS configuration."""

    def __init__(self, reason: str = ""):
        message = "TLS configuration error"
        if reason:
            message += f": {reason}"
        super().__init__(message)


class TLSVersion(IntEnum):
    """TLS protocol versions (from tls_config.h TLSConfigVersion enum)."""

    NOT_SELECTED = _c("TLS_VERSION_NOT_SELECTED", 0)
    SSL_3_0 = _c("TLS_VERSION_SSL_3_0", 3)
    TLS_1_0 = _c("TLS_VERSION_TLS_1_0", 4)
    TLS_1_1 = _c("TLS_VERSION_TLS_1_1", 5)
    TLS_1_2 = _c("TLS_VERSION_TLS_1_2", 6)
    TLS_1_3 = _c("TLS_VERSION_TLS_1_3", 7)


@dataclass
class TLSConfig:
    """
    TLS connection configuration.

    Wraps libiec61850 TLSConfiguration with certificate and key paths.

    A TLS handshake needs a *trust anchor* for the server certificate. There
    are two ways to provide one:

    - **CA trust** (the normal case): pass ``ca_certs``. The server
      certificate is accepted if it chains to one of them.
    - **Certificate pinning**: pass ``allowed_certs`` with
      ``allow_only_known_certs=True`` and ``chain_validation=False``. The
      server certificate is accepted only if it byte-matches a pinned
      certificate — no CA required. This is how you connect to a self-signed
      server; see :meth:`pinning`.

    If you do not have the server's certificate and just want an encrypted
    connection for testing, ``insecure=True`` disables all peer
    authentication (see below). Note that stock libiec61850 has no such mode —
    it is provided by a small patch this package applies to the bundled
    library (``TLSConfiguration_setInsecure``). Without ``insecure``,
    ``chain_validation=False`` alone does NOT accept an unknown certificate;
    the peer must still chain to a CA or match a pinned certificate.

    For mutual TLS, additionally provide ``own_cert`` and ``own_key`` (they
    must be given together).

    Attributes:
        own_cert: Path to own certificate (PEM format)
        own_key: Path to own private key (PEM format)
        key_password: Password of the private key, or None if not protected
        ca_certs: List of paths to CA certificate files
        allowed_certs: List of paths to explicitly allowed (pinned) peer
            certificates (used with allow_only_known_certs)
        chain_validation: Whether to validate the certificate trust chain
        allow_only_known_certs: Only accept peer certificates that match one
            of allowed_certs (certificate pinning)
        time_validation: Whether to check certificate validity times
            (expired / not-yet-valid). Enabled by default; set False to
            tolerate an expired but otherwise-trusted/pinned certificate.
        insecure: Disable ALL peer certificate authentication — accept any
            certificate the server presents. The connection is still
            encrypted but offers NO protection against a man-in-the-middle.
            For testing only; never use in production. Requires no CA or
            pinned certificate.
        min_version: Minimum allowed TLS version (None = library default)
        max_version: Maximum allowed TLS version (None = library default)
    """

    own_cert: str = ""
    own_key: str = ""
    key_password: Optional[str] = None
    ca_certs: List[str] = field(default_factory=list)
    allowed_certs: List[str] = field(default_factory=list)
    chain_validation: bool = True
    allow_only_known_certs: bool = False
    time_validation: bool = True
    insecure: bool = False
    min_version: Optional[TLSVersion] = None
    max_version: Optional[TLSVersion] = None

    @classmethod
    def pinning(
        cls,
        server_cert: str,
        *,
        own_cert: str = "",
        own_key: str = "",
        key_password: Optional[str] = None,
        allow_expired: bool = False,
    ) -> "TLSConfig":
        """Build a config that trusts exactly one pinned server certificate.

        This is the closest libiec61850 offers to an "insecure"/testing mode
        (e.g. against a self-signed server): it accepts the given server
        certificate directly, with no CA, by matching it byte-for-byte. It
        still requires you to have the server's certificate in advance —
        there is no blind accept-any-certificate mode.

        Args:
            server_cert: Path to the server certificate to pin (PEM).
            own_cert / own_key / key_password: Client identity for mutual TLS.
            allow_expired: If True, also tolerate an expired/not-yet-valid
                pinned certificate (sets time_validation=False).
        """
        return cls(
            own_cert=own_cert,
            own_key=own_key,
            key_password=key_password,
            allowed_certs=[server_cert],
            allow_only_known_certs=True,
            chain_validation=False,
            time_validation=not allow_expired,
        )

    def to_dict(self) -> Dict[str, Any]:
        return {
            "own_cert": self.own_cert,
            "own_key": self.own_key,
            "key_password": self.key_password,
            "ca_certs": self.ca_certs,
            "allowed_certs": self.allowed_certs,
            "chain_validation": self.chain_validation,
            "allow_only_known_certs": self.allow_only_known_certs,
            "time_validation": self.time_validation,
            "insecure": self.insecure,
            "min_version": self.min_version,
            "max_version": self.max_version,
        }


def _apply_config(tls_config: Any, config: TLSConfig) -> None:
    """Apply a TLSConfig to a native TLSConfiguration, raising on bad files."""
    if config.own_cert:
        if not iec61850.TLSConfiguration_setOwnCertificateFromFile(tls_config, config.own_cert):
            raise TLSConfigError(f"failed to load own certificate: {config.own_cert}")
        if not iec61850.TLSConfiguration_setOwnKeyFromFile(
            tls_config, config.own_key, config.key_password
        ):
            raise TLSConfigError(f"failed to load own key: {config.own_key}")

    for ca_cert in config.ca_certs:
        if not iec61850.TLSConfiguration_addCACertificateFromFile(tls_config, ca_cert):
            raise TLSConfigError(f"failed to load CA certificate: {ca_cert}")

    for allowed_cert in config.allowed_certs:
        if not iec61850.TLSConfiguration_addAllowedCertificateFromFile(tls_config, allowed_cert):
            raise TLSConfigError(f"failed to load allowed certificate: {allowed_cert}")

    if config.insecure:
        # Accept-any-certificate mode (pyiec61850-ng patch to libiec61850).
        if not hasattr(iec61850, "TLSConfiguration_setInsecure"):
            raise TLSConfigError(
                "TLSConfiguration_setInsecure is missing from this build; "
                "insecure=True is not supported by this wheel"
            )
        iec61850.TLSConfiguration_setInsecure(tls_config, True)

    iec61850.TLSConfiguration_setChainValidation(tls_config, config.chain_validation)
    iec61850.TLSConfiguration_setAllowOnlyKnownCertificates(
        tls_config, config.allow_only_known_certs
    )

    # Time validation is the newest of the three toggles; guard for older
    # mismatched wheels. Only the security-relevant "disable" request must
    # hard-fail if it cannot be honoured — leaving it enabled (the default)
    # on a binding that lacks the setter is safe.
    if hasattr(iec61850, "TLSConfiguration_setTimeValidation"):
        iec61850.TLSConfiguration_setTimeValidation(tls_config, config.time_validation)
    elif not config.time_validation:
        raise TLSConfigError(
            "TLSConfiguration_setTimeValidation is missing from this build; "
            "cannot disable certificate time validation"
        )

    if config.min_version is not None:
        if not hasattr(iec61850, "TLSConfiguration_setMinTlsVersion"):
            raise TLSConfigError("TLS min_version pinning is not supported by this wheel")
        iec61850.TLSConfiguration_setMinTlsVersion(tls_config, int(config.min_version))
    if config.max_version is not None:
        if not hasattr(iec61850, "TLSConfiguration_setMaxTlsVersion"):
            raise TLSConfigError("TLS max_version pinning is not supported by this wheel")
        iec61850.TLSConfiguration_setMaxTlsVersion(tls_config, int(config.max_version))


def create_tls_configuration(config: TLSConfig) -> Any:
    """
    Create a libiec61850 TLSConfiguration from a TLSConfig.

    Args:
        config: TLSConfig with certificate paths

    Returns:
        Native TLSConfiguration object

    Raises:
        LibraryNotFoundError: If pyiec61850 is not available
        TLSConfigError: If configuration is invalid
        TLSError: If TLS configuration creation fails
    """
    require_library(LibraryNotFoundError)

    if not hasattr(iec61850, "TLSConfiguration_create"):
        raise TLSError("TLS not available in SWIG bindings (requires libiec61850 with TLS)")

    # own_cert/own_key come as a pair: mutual TLS needs both, server-auth-only
    # TLS needs neither.
    if config.own_cert and not config.own_key:
        raise TLSConfigError("own_key is required when own_cert is set")
    if config.own_key and not config.own_cert:
        raise TLSConfigError("own_cert is required when own_key is set")

    # insecure=True accepts any certificate, so it needs no trust anchor and
    # bypasses the checks below.
    if config.insecure:
        logger.warning(
            "TLSConfig(insecure=True): peer certificate authentication is "
            "DISABLED — any certificate is accepted. The connection is "
            "encrypted but NOT protected against man-in-the-middle attacks. "
            "Do not use in production."
        )
    else:
        # A handshake needs a trust anchor for the server certificate: either
        # a CA chain (ca_certs) or a pinned certificate (allowed_certs +
        # allow_only_known_certs). Without one, every handshake fails at depth
        # 0 with an opaque connection error, so reject it at config time.
        #   - chain_validation=True always needs ca_certs (pinning alone does
        #     not satisfy the chain check at the leaf).
        #   - chain_validation=False needs either ca_certs or pinning.
        pinning = config.allow_only_known_certs and bool(config.allowed_certs)
        if config.chain_validation and not config.ca_certs:
            raise TLSConfigError(
                "ca_certs is required when chain_validation is enabled (the default); "
                "for a self-signed / pinned server use TLSConfig.pinning(server_cert), "
                "or insecure=True to accept any certificate"
            )
        if not config.chain_validation and not config.ca_certs and not pinning:
            raise TLSConfigError(
                "no trust anchor: provide ca_certs, a pinned server certificate via "
                "TLSConfig.pinning(server_cert), or insecure=True to accept any "
                "certificate"
            )

    tls_config = None
    try:
        tls_config = iec61850.TLSConfiguration_create()
        if not tls_config:
            raise TLSError("Failed to create TLSConfiguration")

        _apply_config(tls_config, config)

        logger.info("TLS configuration created successfully")
        return tls_config

    except Exception as e:
        # Don't leak a half-configured native object.
        destroy_tls_configuration(tls_config)
        if isinstance(e, (TLSError, TLSConfigError)):
            raise
        raise TLSError(f"Failed to create TLS configuration: {e}")


def destroy_tls_configuration(tls_config: Any) -> None:
    """
    Destroy a TLS configuration object.

    Args:
        tls_config: Native TLSConfiguration object
    """
    if not tls_config:
        return

    try:
        if _HAS_IEC61850 and hasattr(iec61850, "TLSConfiguration_destroy"):
            iec61850.TLSConfiguration_destroy(tls_config)
    except Exception as e:
        logger.warning(f"Error destroying TLS configuration: {e}")


def create_tls_connection(tls_config: Any) -> Any:
    """
    Create an IedConnection with TLS support.

    Args:
        tls_config: Native TLSConfiguration object

    Returns:
        IedConnection with TLS configured

    Raises:
        TLSError: If connection creation fails
    """
    require_library(LibraryNotFoundError)

    if not hasattr(iec61850, "IedConnection_createWithTlsSupport"):
        raise TLSError(
            "IedConnection_createWithTlsSupport not available - rebuild with TLS support"
        )

    try:
        conn = iec61850.IedConnection_createWithTlsSupport(tls_config)
        if not conn:
            raise TLSError("Failed to create TLS-enabled IedConnection")
        return conn
    except TLSError:
        raise
    except Exception as e:
        raise TLSError(f"Failed to create TLS connection: {e}")
